&lt;li style=&quot;font-size: 14pt; font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 14pt; font-family: arial, helvetica, sans-serif;&quot;&gt;Ability to work independently and manage time effectively.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 14pt; font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 14pt; font-family: arial, helvetica, sans-serif;&quot;&gt;Strong interpersonal skills.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 14pt; font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 14pt; font-family: arial, helvetica, sans-serif;&quot;&gt;Solid computer skills; prior experience with electronic medical records (EMR) preferred.&lt;/span&gt;&lt;/li&gt;
